{
  "verdict": "reject",
  "findings": [
    {
      "severity": "high",
      "file": "scripts/study_campaign.py",
      "issue": "AccountStop (for unknown actual native/infrastructure failures) improperly consumes the active cell. It marks the cell as failed and advances next_index, unfairly penalizing the cell for a quota/infrastructure pause.",
      "fix": "Catch AccountStop to set the campaign paused state, but do not append a failed step, do not close the cell, and do not advance next_index."
    },
    {
      "severity": "high",
      "file": "scripts/study_campaign.py",
      "issue": "Unhandled exception in Campaign._export causes an infinite crash loop. If a ToolkitCell fails and its partial files exceed the 20,000 byte limit, export_delivery raises a StudyHarnessError outside the try-block, permanently crashing the campaign before progress.json is saved.",
      "fix": "Wrap the self._export() call in a try-except block to safely handle byte ceiling or export errors, allowing the campaign to record the failure without crashing."
    },
    {
      "severity": "high",
      "file": "scripts/software_study_harness.py",
      "issue": "ToolkitCell causes accidental treatment unfairness during final review. It only includes the current sole test ID from engine state, blinding the reviewer to historical failed test receipts, whereas BasicCell includes all historical measurements.",
      "fix": "Retrieve all historical test attempts (including failed receipts) from the controller's log or transport history to populate public-measurements.json for ToolkitCell."
    },
    {
      "severity": "high",
      "file": "scripts/study_cell_budget.py",
      "issue": "CellBudget._clock() fails the cell permanently with a StudyBudgetError if the system's boot_id changes. A normal host reboot should not destroy the running cell.",
      "fix": "Track cumulative elapsed execution time persistently instead of relying on monotonic time bound to a single boot_id, or safely pause the campaign on clock discontinuities."
    },
    {
      "severity": "medium",
      "file": "scripts/study_cell_budget.py",
      "issue": "CellBudget.call() does not enforce the policy['max_rendered_input_bytes'] ceiling (128,000 bytes) for individual prompts, only checking the cumulative budget.",
      "fix": "Add an explicit check 'if size > self.policy[\'max_rendered_input_bytes\']:' before admitting the native job."
    },
    {
      "severity": "medium",
      "file": "scripts/software_study_harness.py",
      "issue": "ToolkitCell lacks isolated terminal failure persistence. If the campaign crashes before saving its progress after catching a ToolkitCell error, the cell will retry the failed step upon resume.",
      "fix": "Persist a terminal-failure.json state within ToolkitCell.step() before throwing/returning the error, matching the crash-safety behavior of BasicCell."
    },
    {
      "severity": "medium",
      "file": "scripts/study_campaign.py",
      "issue": "native_failure_kind() uses an exact string match (raw.strip() in controlled) to classify stderr. Extra standard transport logging or tracebacks will misclassify controlled format errors as unclassified failures.",
      "fix": "Use substring matching (e.g., any(raw.strip().startswith(prefix+msg) for msg in controlled)) to accurately identify controlled native errors."
    }
  ],
  "limitations": [
    "Audit is based on static text analysis without runtime simulation of the full ToolkitCell integration.",
    "Internal mechanics of Controller.package_gate() and engine state structure are assumed to behave as implied by the integration code."
  ],
  "tests_executed": false
}
```

